template:
trait Work {
    fn run(&self) -> i32;
}
struct A;
impl Work for A {
    fn run(&self) -> i32 { 1 }
}
struct B;
impl Work for B {
    fn run(&self) -> i32 { 2 }
}
fn total(xs: &[⟦elem_ty⟧]) -> i32 {
    xs.iter().map(|i| i.run()).sum()
}
fn main() {
    let res = total(&[⟦item1⟧, &B]);
    assert_eq!(res, 3);
}
